public struct FfiConverterTypeFfiEngine: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = FfiEngine

    public static func lift(_ handle: UInt64) throws -> FfiEngine {
        return FfiEngine(unsafeFromHandle: handle)
    }

    public static func lower(_ value: FfiEngine) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiEngine {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: FfiEngine, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


