/**
 * The git half of restore-from-backup can't be a constructor (see
 * `FfiRestoreResult`'s doc comment), so it's exported as a plain function.
 */
public func restoreFromBackup(remoteUrl: String, destPath: String)throws  -> FfiRestoreResult  {
    return try  FfiConverterTypeFfiRestoreResult_lift(try rustCallWithError(FfiConverterTypeFfiEngineError_lift) {
    uniffi_iris_core_fn_func_restore_from_backup(
        FfiConverterString.lower(remoteUrl),
        FfiConverterString.lower(destPath),$0
    )
})
}
/**
 * FFI spike (ADR-031): round-trips a full `Node` — including the fields that
 * forced this DTO layer (timestamps, dates, `crdt_position` YAML) — through
 * the FFI boundary as `FfiNode`, proving the conversion is correct both ways.
 */
public func roundTripNode(ffi: FfiNode)throws  -> FfiNode  {
    return try  FfiConverterTypeFfiNode_lift(try rustCallWithError(FfiConverterTypeFfiConversionError_lift) {
    uniffi_iris_core_fn_func_round_trip_node(
        FfiConverterTypeFfiNode_lower(ffi),$0
    )
})
}
